    title: "Ήχος εκκίνησης Mac πολύ δυνατός; Πώς να τον απενεργοποιήσετε ή να τον χαμηλώσετε",
    description:
      "Ο ήχος εκκίνησης του Mac βροντάει σε πλήρη ένταση κάθε φορά που κάνετε επανεκκίνηση — ιδιαίτερα αμήχανο σε συναντήσεις και ήσυχα δωμάτια. Δείτε πώς να τον σιγάσετε ή να τον ελέγξετε.",
