    description:
      "Ο ήχος του Mac σας χτυπάει, σκάει ή τραυλίζει — κατά τη διάρκεια της αναπαραγωγής μουσικής, κλήσεων ή βίντεο. Εδώ είναι κάθε γνωστή αιτία και επιδιόρθωση για δυσλειτουργίες ήχου macOS.",
    date: "2026-05-16",
